  1→/**
  2→ * Public API endpoint for the storefront zip code widget.
  3→ *
  4→ * Called from the merchant's storefront (Theme App Extension or custom JS)
  5→ * to check whether a zip code is serviceable.
  6→ *
  7→ * GET/POST /api/zip-check?shop=store.myshopify.com&zip=12345
  8→ *
  9→ * Response:
 10→ *   200 { allowed: true,  message: "...", eta: "...", zone: "..." }
 11→ *   200 { allowed: false, message: "..." }
 12→ *   400 { error: "Missing shop or zip parameter" }
 13→ *   404 { allowed: false, message: "Zip code not found", notFound: true }
 14→ */
 15→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→
 18→const CORS_HEADERS = {
 19→  "Access-Control-Allow-Origin": "*",
 20→  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
 21→  "Access-Control-Allow-Headers": "Content-Type",
 22→  "Content-Type": "application/json",
 23→};
 24→
 25→const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9\-]*\.myshopify\.com$/;
 26→
 27→async function handleZipCheck(shop: string | null, zip: string | null) {
 28→  if (!shop || !zip) {
 29→    return new Response(
 30→      JSON.stringify({ error: "Missing shop or zip parameter" }),
 31→      { status: 400, headers: CORS_HEADERS },
 32→    );
 33→  }
 34→
 35→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 36→  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
 37→    return new Response(
 38→      JSON.stringify({ error: "Invalid shop parameter" }),
 39→      { status: 400, headers: CORS_HEADERS },
 40→    );
 41→  }
 42→
 43→  // Enforce input length limits to prevent abuse
 44→  if (zip.length > 20) {
 45→    return new Response(
 46→      JSON.stringify({ error: "Invalid zip code" }),
 47→      { status: 400, headers: CORS_HEADERS },
 48→    );
 49→  }
 50→
 51→  const normalizedZip = zip.trim().toUpperCase();
 52→
 53→  const zipRecord = await db.zipCode.findUnique({
 54→    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
 55→  });
 56→
 57→  // Fetch widget config for custom messages (falls back to defaults)
 58→  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
 59→
 60→  // Fetch shop settings to determine default behavior for unlisted zip codes
 61→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
 62→  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
 63→
 64→  if (!zipRecord || !zipRecord.isActive) {
 65→    const notFoundMsg =
 66→      widgetConfig?.notFoundMessage ??
 67→      "This zip code was not found in our system.";
 68→
 69→    // If the zip is simply not in the list (not inactive) and the merchant
 70→    // has set defaultBehavior to "allow", treat it as an allowed zip
 71→    if (!zipRecord && defaultBehavior === "allow") {
 72→      const successMsg =
 73→        widgetConfig?.successMessage ?? "We deliver to your area!";
 74→      return new Response(
 75→        JSON.stringify({
 76→          allowed: true,
 77→          message: successMsg,
 78→          eta: null,
 79→          zone: null,
 80→          showWaitlist: false,
 81→        }),
 82→        { status: 200, headers: CORS_HEADERS },
 83→      );
 84→    }
 85→
 86→    if (!zipRecord) {
 87→      return new Response(
 88→        JSON.stringify({
 89→          allowed: false,
 90→          message: notFoundMsg,
 91→          notFound: true,
 92→        }),
 93→        { status: 200, headers: CORS_HEADERS },
 94→      );
 95→    }
 96→
 97→    // Inactive zip — treat same as not found regardless of defaultBehavior
 98→    return new Response(
 99→      JSON.stringify({ allowed: false, message: notFoundMsg, notFound: true }),
100→      { status: 200, headers: CORS_HEADERS },
101→    );
102→  }
103→
104→  if (zipRecord.type === "blocked") {
105→    const errorMsg =
106→      zipRecord.message ??
107→      widgetConfig?.errorMessage ??
108→      "Sorry, we don't deliver to this area yet.";
109→
110→    return new Response(
111→      JSON.stringify({ allowed: false, message: errorMsg }),
112→      { status: 200, headers: CORS_HEADERS },
113→    );
114→  }
115→
116→  // Allowed
117→  const successMsg =
118→    zipRecord.message ??
119→    widgetConfig?.successMessage ??
120→    "Great news! We deliver to your area.";
121→
122→  return new Response(
123→    JSON.stringify({
124→      allowed: true,
125→      message: successMsg,
126→      eta: widgetConfig?.showEta ? (zipRecord.eta ?? null) : null,
127→      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
128→      showWaitlist: false,
129→    }),
130→    { status: 200, headers: CORS_HEADERS },
131→  );
132→}
133→
134→// Handle GET requests: ?shop=...&zip=...
135→export const loader = async ({ request }: LoaderFunctionArgs) => {
136→  const url = new URL(request.url);
137→
138→  // Handle CORS preflight
139→  if (request.method === "OPTIONS") {
140→    return new Response(null, { status: 204, headers: CORS_HEADERS });
141→  }
142→
143→  const shop = url.searchParams.get("shop");
144→  const zip = url.searchParams.get("zip");
145→  return handleZipCheck(shop, zip);
146→};
147→
148→// Handle POST requests with JSON body: { shop, zip }
149→export const action = async ({ request }: ActionFunctionArgs) => {
150→  if (request.method === "OPTIONS") {
151→    return new Response(null, { status: 204, headers: CORS_HEADERS });
152→  }
153→
154→  let shop: string | null = null;
155→  let zip: string | null = null;
156→
157→  try {
158→    const body = await request.json();
159→    shop = body?.shop ?? null;
160→    zip = body?.zip ?? null;
161→  } catch {
162→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
163→      status: 400,
164→      headers: CORS_HEADERS,
165→    });
166→  }
167→
168→  return handleZipCheck(shop, zip);
169→};
