  1→/**
  2→ * Public API endpoint — joins a customer to the waitlist from the storefront widget.
  3→ *
  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→
 18→const CORS_HEADERS = {
 19→  "Access-Control-Allow-Origin": "*",
 20→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 21→  "Access-Control-Allow-Headers": "Content-Type",
 22→  "Content-Type": "application/json",
 23→};
 24→
 25→// Handle CORS preflight
 26→export const loader = async ({ request }: LoaderFunctionArgs) => {
 27→  if (request.method === "OPTIONS") {
 28→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 29→  }
 30→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 31→    status: 405,
 32→    headers: CORS_HEADERS,
 33→  });
 34→};
 35→
 36→export const action = async ({ request }: ActionFunctionArgs) => {
 37→  if (request.method === "OPTIONS") {
 38→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 39→  }
 40→
 41→  if (request.method !== "POST") {
 42→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 43→      status: 405,
 44→      headers: CORS_HEADERS,
 45→    });
 46→  }
 47→
 48→  let shop: string | null = null;
 49→  let zip: string | null = null;
 50→  let email: string | null = null;
 51→
 52→  try {
 53→    const body = await request.json();
 54→    shop = body?.shop ?? null;
 55→    zip = body?.zip ?? null;
 56→    email = body?.email ?? null;
 57→  } catch {
 58→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 59→      status: 400,
 60→      headers: CORS_HEADERS,
 61→    });
 62→  }
 63→
 64→  if (!shop || !zip || !email) {
 65→    return new Response(
 66→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 67→      { status: 400, headers: CORS_HEADERS },
 68→    );
 69→  }
 70→
 71→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 72→  if (!/^[a-zA-Z0-9][a-zA-Z0-9\-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 73→    return new Response(
 74→      JSON.stringify({ error: "Invalid shop parameter" }),
 75→      { status: 400, headers: CORS_HEADERS },
 76→    );
 77→  }
 78→
 79→  // Enforce input length limits to prevent abuse
 80→  if (zip.length > 20 || email.length > 254) {
 81→    return new Response(
 82→      JSON.stringify({ error: "Invalid input" }),
 83→      { status: 400, headers: CORS_HEADERS },
 84→    );
 85→  }
 86→
 87→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
 88→    return new Response(
 89→      JSON.stringify({ error: "Invalid email address" }),
 90→      { status: 400, headers: CORS_HEADERS },
 91→    );
 92→  }
 93→
 94→  try {
 95→    await db.waitlistEntry.upsert({
 96→      where: {
 97→        shop_email_zipCode: {
 98→          shop,
 99→          email,
100→          zipCode: zip.trim().toUpperCase(),
101→        },
102→      },
103→      create: {
104→        shop,
105→        email,
106→        zipCode: zip.trim().toUpperCase(),
107→        status: "waiting",
108→      },
109→      update: {
110→        status: "waiting",
111→      },
112→    });
113→
114→    return new Response(
115→      JSON.stringify({
116→        success: true,
117→        message: "You've been added to the waitlist!",
118→      }),
119→      { status: 200, headers: CORS_HEADERS },
120→    );
121→  } catch {
122→    return new Response(
123→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
124→      { status: 500, headers: CORS_HEADERS },
125→    );
126→  }
127→};
