 1→import type { ActionFunctionArgs } from "react-router";
 2→import { authenticate } from "../shopify.server";
 3→import { syncSubscriptionFromShopify } from "../billing.server";
 4→
 5→export const action = async ({ request }: ActionFunctionArgs) => {
 6→  const { shop, payload } = await authenticate.webhook(request);
 7→
 8→  console.log(`Received app_subscriptions/update webhook for ${shop}`);
 9→
10→  try {
11→    type SubscriptionPayload = {
12→      app_subscription?: {
13→        admin_graphql_api_id?: string;
14→        name?: string;
15→        status?: string;
16→      };
17→    };
18→
19→    const data = payload as SubscriptionPayload;
20→    const sub = data?.app_subscription;
21→
22→    if (sub) {
23→      await syncSubscriptionFromShopify(shop, [
24→        {
25→          id: sub.admin_graphql_api_id ?? "",
26→          name: sub.name ?? "",
27→          status: sub.status ?? "",
28→        },
29→      ]);
30→      console.log(`Synced subscription for ${shop}: ${sub.name} → ${sub.status}`);
31→    }
32→  } catch (err) {
33→    console.error(`Failed to sync subscription for ${shop}:`, err);
34→  }
35→
36→  return new Response();
37→};
