16→
17→  console.log(`Received ${topic} webhook for ${shop}`);
18→
19→  const customerId = payload?.customer?.id;
20→  const customerEmail = payload?.customer?.email;
21→
22→  // Log the data request for manual fulfilment or integrate with your
