 1→import type { ActionFunctionArgs } from "react-router";
 2→import { authenticate } from "../shopify.server";
 3→import db from "../db.server";
 4→
 5→export const action = async ({ request }: ActionFunctionArgs) => {
 6→  const { shop, session, topic } = await authenticate.webhook(request);
 7→
 8→  console.log(`Received ${topic} webhook for ${shop}`);
 9→
10→  // Webhook requests can trigger multiple times and after an app has already been uninstalled.
11→  // Delete all shop data immediately on uninstall (Shopify App Store requirement).
12→  // The shop/redact GDPR webhook fires 48 hours later and also runs this cleanup.
13→  if (session) {
14→    await Promise.all([
15→      db.session.deleteMany({ where: { shop } }),
16→      db.zipCode.deleteMany({ where: { shop } }),
17→      db.deliveryRule.deleteMany({ where: { shop } }),
18→      db.waitlistEntry.deleteMany({ where: { shop } }),
19→      db.widgetConfig.deleteMany({ where: { shop } }),
20→      db.subscription.deleteMany({ where: { shop } }),
21→      db.shopSettings.deleteMany({ where: { shop } }),
22→    ]);
23→  }
24→
25→  return new Response();
26→};
