152→  function wireWidget(wid, cfg, API_BASE, SHOP) {
153→    var inp = document.getElementById(wid + "-inp");
154→    var btn = document.getElementById(wid + "-btn");
155→    var res = document.getElementById(wid + "-res");
156→    var btnLabel = cfg.buttonText;
157→    if (!inp || !btn || !res) return;
158→
159→    function checkZip() {
160→      var zip = inp.value.trim();
161→      if (!zip) { inp.focus(); return; }
162→
163→      btn.disabled = true;
164→      btn.textContent = "\u2026";
165→      res.innerHTML = "";
166→
167→      fetch(
168→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
169→          "&zip=" + encodeURIComponent(zip)
170→      )
171→        .then(function (r) { return r.json(); })
172→        .then(function (data) {
173→          btn.disabled = false;
174→          btn.textContent = btnLabel;
175→
176→          if (data.allowed) {
177→            var html = '<div class="zcc-result ok">' + esc(data.message);
178→            if (cfg.showEta && data.eta) {
179→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
180→            }
181→            if (cfg.showZone && data.zone) {
182→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
183→            }
184→            html += "</div>";
185→            res.innerHTML = html;
186→          } else {
187→            var html = '<div class="zcc-result fail">' + esc(data.message);
188→            if (cfg.showWaitlistOnFailure) {
189→              html +=
190→                '<div class="zcc-wl">' +
191→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
192→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
193→                "</div>";
194→            }
195→            html += "</div>";
196→            res.innerHTML = html;
197→
198→            if (cfg.showWaitlistOnFailure) {
199→              var wBtn = document.getElementById(wid + "-wl-btn");
200→              if (wBtn) {
201→                wBtn.addEventListener("click", function () {
202→                  var emailEl = document.getElementById(wid + "-wl-email");
203→                  var email = emailEl ? emailEl.value.trim() : "";
204→                  if (!email) { if (emailEl) emailEl.focus(); return; }
205→                  joinWaitlist(zip, email, wBtn);
206→                });
207→              }
208→            }
209→          }
210→        })
211→        .catch(function () {
212→          btn.disabled = false;
213→          btn.textContent = btnLabel;
214→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
215→        });
216→    }
217→
218→    btn.addEventListener("click", checkZip);
219→    inp.addEventListener("keydown", function (e) {
220→      if (e.key === "Enter") checkZip();
221→    });
222→  }
223→
224→  function joinWaitlist(zip, email, wBtn) {
225→    wBtn.disabled = true;
226→    wBtn.textContent = "Joining\u2026";
227→
228→    fetch(API_BASE + "/api/waitlist", {
229→      method: "POST",
230→      headers: { "Content-Type": "application/json" },
231→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
232→    })
233→      .then(function (r) { return r.json(); })
234→      .then(function (data) {
235→        var wlEl = wBtn.closest(".zcc-wl");
236→        if (data.success) {
237→          if (wlEl) wlEl.innerHTML =
238→            '<p style="font-size:13px;margin:6px 0 0">' +
239→            "\u2713 You\u2019ve been added to the waitlist!" +
240→            "</p>";
241→        } else {
242→          wBtn.disabled = false;
243→          wBtn.textContent = "Join Waitlist";
244→        }
245→      })
246→      .catch(function () {
247→        wBtn.disabled = false;
248→        wBtn.textContent = "Join Waitlist";
249→      });
250→  }
