413→  function esc(str) {
414→    return String(str)
415→      .replace(/&/g, "&amp;")
416→      .replace(/</g, "&lt;")
417→      .replace(/>/g, "&gt;")
418→      .replace(/"/g, "&quot;");
419→  }
420→
421→  function escAttr(str) {
422→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
423→  }
424→})();
425→</script>
